// 「自由一日之后」是校园活动结束后的原创同人任务。
function freeDayChoice(text, next, result, {
  blood = 0, spirit = 0, favor = 0, flags = [], requiredFlag = '', requiredReason = '',
} = {}) {
  return {text, next, result, blood, spirit, favor, flags, requiredFlag, requiredReason, requiredSpirit: 0};
}

function freeDayScene(title, paragraphs, choices = []) {
  return {title, text: paragraphs.join('\n\n'), choices, ending: choices.length === 0};
}

export const FREE_CHAPTERS = [
  ['free_arrival'], ['free_desk'], ['free_room', 'free_hall'],
  ['free_lockers', 'free_steps'], ['free_compare'], ['free_student'],
  ['free_signatures'], ['free_report'],
];

export const FREE_ENDINGS = ['free_ending_revision', 'free_ending_receipt', 'free_ending_wait'];

export function freeDayEnding(state) {
  const has = flag => state.flags.includes(flag);
  if (has('free_filed') && has('free_timeline') && has('free_consent') && has('free_both_signed')) {
    return 'free_ending_revision';
  }
  if (has('free_private') || has('free_filed')) {
    return 'free_ending_receipt';
  }
  return 'free_ending_wait';
}

